3|export function emptyScalarPosition(
4|  offset: number,
5|  before: Token[] | undefined,
6|  pos: number | null
7|) {
8|  if (before) {
9|    if (pos === null) pos = before.length
10|    for (let i = pos - 1; i >= 0; --i) {
11|      let st = before[i]
12|      switch (st.type) {
13|        case 'space':
14|        case 'comment':
15|        case 'newline':
16|          offset -= st.source.length
17|          continue
18|      }
19|
20|      // Technically, an empty scalar is immediately after the last non-empty
21|      // node, but it's more useful to place it after any whitespace.
22|      st = before[++i]
23|      while (st?.type === 'space') {
24|        offset += st.source.length
25|        st = before[++i]
26|      }
27|      break
28|    }
